package privateadmin.internal

import android.app.*
import android.os.Bundle
import android.view.Gravity
import android.view.View
import android.widget.*
import androidx.activity.ComponentActivity
import androidx.lifecycle.lifecycleScope
import kotlinx.coroutines.launch
import org.json.JSONArray
import org.json.JSONObject

class MainActivity:ComponentActivity() {
 private val api=SupabaseApi()
 private lateinit var dao:LocalDao
 private lateinit var sync:SyncEngine
 private var lang=UiLanguage.EN
 private var body:LinearLayout?=null
 private fun tr(a:String,b:String,c:String)=uiText(a,b,c,lang)
 override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);dao=LocalDb.get(this).dao();sync=SyncEngine(api,dao);lang=runCatching{UiLanguage.valueOf(getPreferences(0).getString("lang","EN")!!)}.getOrDefault(UiLanguage.EN)
  val p=getPreferences(0);if(p.contains("access")){api.session=Session(p.getString("access","")!!,p.getString("refresh","")!!,p.getLong("expiry",0));home()}else login()
 }
 private fun screen(title:String,back:Boolean=true){val root=LinearLayout(this).apply{orientation=1;setPadding(20,16,20,16);setBackgroundColor(0xfff5f7fb.toInt())};val header=LinearLayout(this).apply{orientation=0;gravity=Gravity.CENTER_VERTICAL}
  if(back)header.addView(button("‹",false){home()},LinearLayout.LayoutParams(52,52))
  header.addView(text(title,22,true),LinearLayout.LayoutParams(0,-2,1f));root.addView(header)
  val scroll=ScrollView(this);body=LinearLayout(this).apply{orientation=1};scroll.addView(body);root.addView(scroll,LinearLayout.LayoutParams(-1,0,1f));setContentView(root)
 }
 private fun text(s:String,size:Int=16,bold:Boolean=false)=TextView(this).apply{text=s;textSize=size.toFloat();setTextColor(0xff17243a.toInt());if(bold)typeface=android.graphics.Typeface.DEFAULT_BOLD;setPadding(4,10,4,10)}
 private fun add(v:View){body?.addView(v,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=6})}
 private fun button(s:String,primary:Boolean=true,fn:()->Unit)=Button(this).apply{text=s;isAllCaps=false;setOnClickListener{fn()};if(primary)setTextColor(0xff17345c.toInt())}
 private fun input(h:String,v:String="")=EditText(this).apply{hint=h;setText(v);textSize=16f}
 private fun task(fn:suspend()->Unit){lifecycleScope.launch{try{fn()}catch(e:Exception){toast(e.message?: "Request failed")}}}
 private fun toast(s:String){Toast.makeText(this,s,Toast.LENGTH_LONG).show()}
 private fun login(){screen("Sign in",false);add(text("Private owner access",18,true));val email=input("Email");val pass=input("Password");pass.inputType=129;add(email);add(pass);add(button("Sign in"){task{val s=api.signIn(email.text.toString().trim(),pass.text.toString());getPreferences(0).edit().putString("access",s.access).putString("refresh",s.refresh).putLong("expiry",s.expiresAt).apply();home()}})}
 private fun home(){screen("MDM Admin",false);add(text(tr("Published changes sync to the app.","प्रकाशित बदलाव ऐप में सिंक होंगे।","ਪ੍ਰਕਾਸ਼ਿਤ ਤਬਦੀਲੀਆਂ ਐਪ ਵਿੱਚ ਸਿੰਕ ਹੋਣਗੀਆਂ।"),14))
  val language=Spinner(this);language.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,listOf("English","हिन्दी","ਪੰਜਾਬੀ"));language.setSelection(lang.ordinal);language.onItemSelectedListener=object:android.widget.AdapterView.OnItemSelectedListener{override fun onNothingSelected(p:android.widget.AdapterView<*>?){};override fun onItemSelected(p:android.widget.AdapterView<*>?,v:View?,pos:Int,id:Long){lang=UiLanguage.values()[pos];getPreferences(0).edit().putString("lang",lang.name).apply()}};add(language)
  add(button(tr("Sync now","अभी सिंक करें","ਹੁਣੇ ਸਿੰਕ ਕਰੋ")){task{toast("Synced · revision "+sync.sync())}})
  add(button(tr("Route List","रूट सूची","ਰੂਟ ਸੂਚੀ")){routeList()});add(button(tr("Bus Stop List","बस स्टॉप सूची","ਬੱਸ ਸਟਾਪ ਸੂਚੀ")){placeList()})
  add(button(tr("Recycle Bin","रीसायकल बिन","ਰੀਸਾਈਕਲ ਬਿਨ")){recycle()});add(button(tr("Review Center","रिव्यू सेंटर","ਰੀਵਿਊ ਸੈਂਟਰ")){reviews()})
  add(button(tr("Add Route","रूट जोड़ें","ਰੂਟ ਜੋੜੋ")){editRoute(null)});add(button(tr("Correction Route","रूट सुधारें","ਰੂਟ ਸੋਧੋ")){routeList()});add(button(tr("Add Bus Stop","बस स्टॉप जोड़ें","ਬੱਸ ਸਟਾਪ ਜੋੜੋ")){editPlace(null)})
  add(button("Sign out",false){api.session=null;getPreferences(0).edit().clear().apply();login()})
  task{SnapshotSeeder.seed(assets,dao);sync.sync()}
 }
 private fun placeName(p:PlaceRow):String{val n=JSONObject(p.names);return n.optString("en").ifBlank{n.optString("hi").ifBlank{n.optString("pa").ifBlank{p.id}}}}
 private fun routeList(){screen(tr("Route List","रूट सूची","ਰੂਟ ਸੂਚੀ"));val q=input("Search routes");add(q);task{sync.sync();showRoutes("")};q.addTextChangedListener(object:android.text.TextWatcher{override fun beforeTextChanged(s:CharSequence?,st:Int,c:Int,a:Int){};override fun onTextChanged(s:CharSequence?,st:Int,b:Int,c:Int){lifecycleScope.launch{showRoutes(s.toString())}};override fun afterTextChanged(e:android.text.Editable?){}})}
 private suspend fun showRoutes(q:String){val rows=dao.allRoutes().filter{it.fromId.contains(q,true)||it.toId.contains(q,true)||it.id.contains(q,true)};body?.removeViews(1,(body?.childCount?:1)-1);add(text(rows.size.toString()+" routes",13));if(rows.isEmpty())add(text("No matches"));rows.forEach{r->add(button(r.fromId+" → "+r.toId+"  "+(r.time?:"")){routeDetail(r)})}}
 private fun routeDetail(r:RouteRow){val j=JSONObject(r.payload);screen("Route details");add(text(r.fromId+" → "+r.toId,20,true));add(text(j.optJSONArray("stops")?.toString()?:""));add(button("Correct this route"){editRoute(r)});add(button("Copy Route"){editRoute(r,true)});add(button("Return Route"){editRoute(r,false,true)});add(button("Delete route",false){confirm("Delete route?"){task{val res=publishChange("route",r.id,"delete",j);toast("Published successfully · revision "+res.optLong("revision"));sync.sync();routeList()}}})}
 private fun publishChange(type:String,id:String,op:String,payload:JSONObject)=api.publish(JSONObject().put("action","publish").put("changes",JSONArray().put(JSONObject().put("entity_type",type).put("entity_id",id).put("operation",op).put("payload",payload))))
 private fun editRoute(old:RouteRow?,copy:Boolean=false,reverse:Boolean=false){screen(if(old==null)"Add Route" else "Route Editor");task{
  sync.sync();val places=dao.allPlaces();if(places.size<2)throw IllegalStateException("Add at least two bus stops first.")
  val labels=places.map{placeName(it)};val from=Spinner(this);from.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,labels);val to=Spinner(this);to.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,labels)
  val oldJson=old?.let{JSONObject(it.payload)};val start=input("Start time HH:mm",if(copy||reverse)"" else oldJson?.optString("time","")?:"");val service=input("Service / bus name (optional)",if(copy)"" else oldJson?.optString("service","")?:"");val contact=input("Contact");val info=input("Info")
  add(text("Start place"));add(from);add(text("Destination"));add(to);add(start);add(service);add(contact);add(info)
  val long=CheckBox(this).apply{text="Long route";isChecked=oldJson?.optBoolean("longRoute")?:false};add(long);val date=input("Start date YYYY-MM-DD",oldJson?.optString("startDate","")?:"");add(date)
  val stopPick=Spinner(this);stopPick.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,labels);val stopTime=input("Intermediate stop time HH:mm (optional)");val stops=mutableListOf<Pair<String,String?>>();val stopText=text("")
  add(text("Intermediate stop"));add(stopPick);add(stopTime);add(button("Add stop"){val p=places[stopPick.selectedItemPosition];stops.add(p.id to stopTime.text.toString().ifBlank{null});stopText.text=stops.joinToString(" → "){it.first};stopTime.setText("")});add(stopText)
  if(oldJson!=null){from.setSelection(places.indexOfFirst{it.id==if(reverse)oldJson.optString("to") else oldJson.optString("from")}.coerceAtLeast(0));to.setSelection(places.indexOfFirst{it.id==if(reverse)oldJson.optString("from") else oldJson.optString("to")}.coerceAtLeast(0));oldJson.optJSONArray("stops")?.let{a->if(reverse){for(i in a.length()-1 downTo 0){val s=a.optJSONObject(i)?:continue;stops.add(s.optString("place") to null)}}else{for(i in 0 until a.length()){val s=a.optJSONObject(i)?:continue;stops.add(s.optString("place") to if(copy)null else s.optString("time").ifBlank{null})}}};stopText.text=stops.joinToString(" → "){it.first}}
  add(button("Preview route"){toast(labels[from.selectedItemPosition]+" → "+stops.joinToString(" → "){it.first}+" → "+labels[to.selectedItemPosition])})
  add(button("Publish route"){task{val f=places[from.selectedItemPosition];val d=places[to.selectedItemPosition];val sequence=listOf(f.id)+stops.map{it.first}+d.id;val circular=sequence.size>=3&&sequence.first()==sequence.last()&&sequence.dropLast(1).distinct().size==sequence.size-1;if(sequence.distinct().size<2||sequence.distinct().size!=sequence.size&&!circular)throw IllegalStateException("Route has repeated or invalid stops");val timeOk=Regex("^([01]\\d|2[0-3]):[0-5]\\d$");if(!timeOk.matches(start.text.toString())&&stops.none{it.second?.let(timeOk::matches)==true})throw IllegalStateException("At least one valid HH:mm time is required")
   val id=old?.id?.takeIf{!copy&&!reverse}?:("r_"+System.currentTimeMillis());val payload=JSONObject().put("id",id).put("from",f.id).put("to",d.id).put("time",start.text.toString()).put("service",service.text.toString()).put("contact",contact.text.toString()).put("info",info.text.toString()).put("longRoute",long.isChecked).put("stops",JSONArray().apply{stops.forEach{put(JSONObject().put("place",it.first).put("time",it.second?:JSONObject.NULL))}});if(long.isChecked)payload.put("startDate",date.text.toString());val res=publishChange("route",id,"upsert",payload);toast("Published successfully · revision "+res.optLong("revision"));sync.sync();home()}})
 }}
 private fun placeList(){screen("Bus Stop List");val q=input("Search stops");add(q);task{sync.sync();showPlaces("")};q.addTextChangedListener(object:android.text.TextWatcher{override fun beforeTextChanged(s:CharSequence?,st:Int,c:Int,a:Int){};override fun onTextChanged(s:CharSequence?,st:Int,b:Int,c:Int){lifecycleScope.launch{showPlaces(s.toString())}};override fun afterTextChanged(e:android.text.Editable?){}})}
 private suspend fun showPlaces(q:String){val rows=dao.allPlaces().filter{it.id.contains(q,true)||it.names.contains(q,true)};body?.removeViews(1,(body?.childCount?:1)-1);add(text(rows.size.toString()+" places",13));rows.forEach{p->add(button(placeName(p)){screen(placeName(p));add(text(p.names));add(button("Correct this stop"){editPlace(p)});add(button("Delete this stop",false){task{val used=dao.allRoutes().filter{r->val j=JSONObject(r.payload);j.optString("from")==p.id||j.optString("to")==p.id||(j.optJSONArray("stops")?.let{a->(0 until a.length()).any{a.optJSONObject(it)?.optString("place")==p.id}}?:false)};if(used.isNotEmpty())toast("Cannot delete this stop: "+used.joinToString{it.id})else confirm("Delete this stop?"){task{val payload=JSONObject(p.payload);val res=publishChange("place",p.id,"delete",payload);toast("Published successfully · revision "+res.optLong("revision"));sync.sync();placeList()}}}})})}}
 private fun editPlace(old:PlaceRow?){screen(if(old==null)"Add Bus Stop" else "Correction Bus Stop");val kind=Spinner(this);kind.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,listOf("Bus Stand","Village","City","Other Place"));kind.setSelection(when(old?.kind){"stand"->0;"village"->1;"city"->2;else->3});add(kind);val n=JSONObject(old?.names?:"{}");val en=input("English",n.optString("en"));val hi=input("Hindi",n.optString("hi"));val pa=input("Punjabi",n.optString("pa"));add(en);add(hi);add(pa);add(button("Preview"){toast(listOf(en.text,hi.text,pa.text).joinToString(" · "))});add(button("Publish"){task{if(en.text.isBlank()&&hi.text.isBlank()&&pa.text.isBlank())throw IllegalStateException("At least one name is required");val slug=en.text.toString().ifBlank{hi.text.toString().ifBlank{pa.text.toString()}}.lowercase().replace(Regex("[^a-z0-9]+"),"_").trim('_').take(65);val id=old?.id?:slug.ifBlank{"place_"+System.currentTimeMillis()};val payload=JSONObject(old?.payload?:"{}");val names=payload.optJSONObject("name")?:JSONObject();if(en.text.isNotBlank())names.put("en",en.text.toString());if(hi.text.isNotBlank())names.put("hi",hi.text.toString());if(pa.text.isNotBlank())names.put("pa",pa.text.toString());payload.put("id",id).put("kind",if(kind.selectedItemPosition==0)"stand" else "place").put("name",names);val p=payload;val res=publishChange("place",id,"upsert",p);toast("Published successfully · revision "+res.optLong("revision"));sync.sync();home()}})}
 private fun recycle(){screen("Recycle Bin");task{val a=api.publish(JSONObject().put("action","recycle-list")).optJSONArray("items")?:JSONArray();if(a.length()==0)add(text("Recycle Bin is empty."));for(i in 0 until a.length()){val x=a.getJSONObject(i);val id=x.optLong("id");add(text(x.optString("entity_type")+" · "+x.optString("entity_id")+" · "+x.optString("deleted_at")));add(button("Restore"){task{val r=api.publish(JSONObject().put("action","recycle-restore").put("id",id));toast("Restored · revision "+r.optLong("revision"));sync.sync();recycle()}});add(button("Permanent Delete",false){confirm("This removes the recovery copy permanently."){task{api.publish(JSONObject().put("action","recycle-purge").put("id",id));recycle()}}})}}}
 private fun reviews(){screen("Review Center");add(button("Refresh"){reviews()});task{val j=api.publish(JSONObject().put("action","review-list"));val tables=listOf("bus_operator_submissions","route_submissions","correction_submissions","feedback_submissions");for(table in tables){val a=j.optJSONArray(table)?:JSONArray();add(text(table.replace("_"," ").uppercase()+" ("+a.length()+")",17,true));if(a.length()==0)add(text("No requests in this section."));for(i in 0 until a.length()){val x=a.getJSONObject(i);val id=x.optString("id");val summary=x.optString("operator_name",x.optString("from_text",x.optString("message",x.optString("notes","Request"))));add(text(summary+" · "+x.optString("status")));if(table=="feedback_submissions"){add(text("Read-only feedback. No approval or editing is available."));add(button("Mark reviewed"){setStatus(table,id,"reviewed")})}else{add(button("Edit"){editReview(table,x)});listOf("pending","reviewed","approved","rejected").forEach{status->add(button(status){setStatus(table,id,status)})};add(button("Delete",false){confirm("Delete request?"){setStatus(table,id,"deleted")}})}}}}}
 private fun setStatus(table:String,id:String,status:String){task{api.publish(JSONObject().put("action","review-status").put("table",table).put("id",id).put("status",status));reviews()}}
 private fun editReview(table:String,x:JSONObject){val keys=when(table){"route_submissions"->listOf("from_text","to_text","start_time","service_name","phone","route_text");"correction_submissions"->listOf("notes","phone","missing_place_name","missing_time","corrected_time","change_summary");else->listOf("operator_name","service_name","bus_type","seat_type","sleeper_count","seater_count","from_text","to_text","location","phone","whatsapp","details")};val fields=JSONObject();val inputs=keys.associateWith{input(it,x.optString(it))};val box=LinearLayout(this).apply{orientation=1;inputs.values.forEach{addView(it)}};AlertDialog.Builder(this).setTitle("Edit request").setView(ScrollView(this).apply{addView(box)}).setNegativeButton("Cancel",null).setPositiveButton("Save"){_,_->task{if(table=="bus_operator_submissions"&&(inputs["operator_name"]?.text.isNullOrBlank()||inputs["phone"]?.text.isNullOrBlank()))throw IllegalStateException("Operator name and mobile are required");inputs.forEach{(k,v)->if(v.text.isNotBlank())fields.put(k,v.text.toString())};api.publish(JSONObject().put("action","review-edit").put("table",table).put("id",x.optString("id")).put("fields",fields));reviews()}}.show()}
 private fun confirm(message:String,yes:()->Unit){AlertDialog.Builder(this).setMessage(message).setNegativeButton("Cancel",null).setPositiveButton("Confirm"){_,_->yes()}.show()}
}
